166	// AccountStatus implements harnesses.AccountHarness. Claude embeds
167	// account/plan info inside its quota probe, so this method projects the
168	// quota cache's Account field onto AccountSnapshot.
169	func (r *Runner) AccountStatus(ctx context.Context, now time.Time) (harnesses.AccountSnapshot, error) {
170		if err := ctx.Err(); err != nil {
171			return harnesses.AccountSnapshot{}, err
172		}
173		snap, ok := readClaudeQuota()
174		if !ok || snap == nil {
175			return harnesses.AccountSnapshot{Source: "cache"}, nil
176		}
177		return claudeAccountSnapshotFromQuotaSnapshot(snap, now), nil
178	}
179	
180	// RefreshAccount implements harnesses.AccountHarness by driving the
181	// quota probe (which carries account evidence) and projecting the
182	// resulting cached snapshot onto AccountSnapshot.
183	func (r *Runner) RefreshAccount(ctx context.Context) (harnesses.AccountSnapshot, error) {
184		if _, err := r.RefreshQuota(ctx); err != nil {
185			return harnesses.AccountSnapshot{}, err
186		}
187		return r.AccountStatus(ctx, time.Now())
188	}
189	
190	// AccountFreshness implements harnesses.AccountHarness.
191	func (r *Runner) AccountFreshness() time.Duration {
192		return claudeAccountFreshness
193	}
194	
195	// DefaultModelSnapshot implements harnesses.ModelDiscoveryHarness. It calls
196	// the live PTY discovery helper with a sensible timeout; on failure,
197	// returns ErrModelDiscoveryEvidenceMissing per the no-static-fallback principle.
198	func (r *Runner) DefaultModelSnapshot() (harnesses.ModelDiscoverySnapshot, error) {
199		timeout := 10 * time.Second
200		var opts []QuotaPTYOption
201		if r.Binary != "" {
202			opts = append(opts, WithQuotaPTYCommand(r.Binary))
203		}
204		snapshot, err := ReadClaudeModelDiscoveryViaPTY(timeout, opts...)
205		if err != nil {
206			return harnesses.ModelDiscoverySnapshot{}, fmt.Errorf("model discovery PTY: %w", err)
207		}
208		if len(snapshot.Models) == 0 {
209			return harnesses.ModelDiscoverySnapshot{}, harnesses.ErrModelDiscoveryEvidenceMissing
210		}
211		return snapshot, nil
212	}
213	
214	// ResolveModelAlias implements harnesses.ModelDiscoveryHarness. Returns
215	// harnesses.ErrAliasNotResolvable when the supplied family is not a
216	// recognized claude alias or when the supplied discovery snapshot has
217	// no concrete model matching the family.
218	func (r *Runner) ResolveModelAlias(family string, snapshot harnesses.ModelDiscoverySnapshot) (string, error) {
219		normalized := strings.ToLower(strings.TrimSpace(family))
220		if !isSupportedClaudeAlias(normalized) {
221			return "", harnesses.ErrAliasNotResolvable
222		}
223		resolved := resolveClaudeFamilyAlias(normalized, snapshot)
224		if resolved == "" {
225			return "", harnesses.ErrAliasNotResolvable
226		}
227		return resolved, nil
228	}
229	
230	// SupportedAliases implements harnesses.ModelDiscoveryHarness.
231	func (r *Runner) SupportedAliases() []string {
232		return append([]string(nil), supportedAliases...)
233	}
234	
235	func isSupportedClaudeAlias(family string) bool {
236		for _, a := range supportedAliases {
237			if a == family {
238				return true
239			}
240		}
241		return false
242	}
243	
244	// claudeQuotaStatusFromSnapshot projects the per-harness snapshot onto
245	// harnesses.QuotaStatus, deriving State and RoutingPreference via the
246	// existing internal routing helper so today's "PreferClaude +
247	// freshness" semantics map cleanly onto CONTRACT-004's RoutingPreference
248	// enum.
249	func claudeQuotaStatusFromSnapshot(snap *claudeQuotaSnapshot, now time.Time) harnesses.QuotaStatus {
250		decision := decideClaudeQuotaRouting(snap, now, claudeQuotaFreshness)
251		pref, state := mapClaudeRoutingPreference(decision)
252		status := harnesses.QuotaStatus{
253			Source:            snap.Source,
254			CapturedAt:        snap.CapturedAt,
255			Fresh:             decision.Fresh,
256			Age:               decision.Age,
257			State:             state,
258			Windows:           append([]harnesses.QuotaWindow(nil), snap.Windows...),
259			RoutingPreference: pref,
260			Reason:            quotaReasonForProjection(decision, state),
261		}
262		if snap.Account != nil {
263			acct := claudeAccountSnapshotFromQuotaSnapshot(snap, now)
264			status.Account = &acct
265		}
266		return status
267	}
268	
269	// quotaReasonForProjection trims the routing decision's diagnostic
270	// reason so QuotaStatus.Reason carries information only when it adds
271	// value beyond the State enum. The trivial QuotaOK success path
272	// ("fresh snapshot has headroom") is suppressed so the public Status
273	// string matches the contract-003 fixture (bare "ok"). All non-OK
274	// states keep the decision reason because it surfaces why the state is
275	// not ok (stale snapshot, incomplete account, exhausted window).
276	func quotaReasonForProjection(decision claudeQuotaRoutingDecision, state harnesses.QuotaStateValue) string {
277		if state == harnesses.QuotaOK {
278			return ""
279		}
280		return decision.Reason
281	}
282	
283	// mapClaudeRoutingPreference translates today's PreferClaude+freshness
284	// decision into the CONTRACT-004 (RoutingPreference, QuotaStateValue)
285	// pair. Legacy semantics: missing snapshot ⇒ Unavailable/Unknown;
286	// stale ⇒ Stale/Blocked ("assume limited"); fresh+PreferClaude ⇒
287	// OK/Available; fresh+!PreferClaude ⇒ Blocked/Blocked.
288	func mapClaudeRoutingPreference(d claudeQuotaRoutingDecision) (harnesses.RoutingPreference, harnesses.QuotaStateValue) {
289		if !d.SnapshotPresent {
290			return harnesses.RoutingPreferenceUnknown, harnesses.QuotaUnavailable
291		}
292		if !d.Fresh {
293			return harnesses.RoutingPreferenceBlocked, harnesses.QuotaStale
294		}
295		if d.PreferClaude {
296			return harnesses.RoutingPreferenceAvailable, harnesses.QuotaOK
297		}
298		return harnesses.RoutingPreferenceBlocked, harnesses.QuotaBlocked
299	}
300	
301	// claudeAccountSnapshotFromQuotaSnapshot derives an AccountSnapshot from
302	// the quota cache's embedded Account field. Plan-type "unknown" (written
303	// by markClaudeQuotaExhaustedFromMessage on runtime errors) is reported
304	// as unauthenticated evidence rather than positive authentication.
305	func claudeAccountSnapshotFromQuotaSnapshot(snap *claudeQuotaSnapshot, now time.Time) harnesses.AccountSnapshot {
306		out := harnesses.AccountSnapshot{
307			Source:     "cache",
308			CapturedAt: snap.CapturedAt,
309			Fresh:      isClaudeQuotaFresh(snap, now, claudeAccountFreshness),
310		}
311		if snap.Account == nil {
312			return out
313		}
314		plan := strings.TrimSpace(snap.Account.PlanType)
315		out.PlanType = plan
316		out.Email = snap.Account.Email
317		out.OrgName = snap.Account.OrgName
318		switch {
319		case plan == "" || strings.EqualFold(plan, "unknown"):
320			out.Unauthenticated = true
321		default:
322			out.Authenticated = true
323		}
324		return out
325	}
326	
327	// Compile-time interface satisfaction.
328	var (
329		_ harnesses.Harness               = (*Runner)(nil)
330		_ harnesses.QuotaHarness          = (*Runner)(nil)
331		_ harnesses.AccountHarness        = (*Runner)(nil)
332		_ harnesses.ModelDiscoveryHarness = (*Runner)(nil)
333	)
