1	package claude
2	
3	import (
4		"context"
5		"fmt"
6		"os/exec"
7		"regexp"
8		"strings"
9		"time"
10	
11		"github.com/easel/fizeau/internal/harnesses"
12		"github.com/easel/fizeau/internal/harnesses/ptyquota"
13		"github.com/easel/fizeau/internal/pty/cassette"
14		"github.com/easel/fizeau/internal/pty/session"
15	)
16	
17	const ClaudeModelDiscoveryFreshnessWindow = 24 * time.Hour
18	
19	var (
20		claudeFullModelPattern         = regexp.MustCompile(`\bclaude-[a-z0-9][a-z0-9._-]*\b`)
21		claudeFullFamilyVersionPattern = regexp.MustCompile(`\bclaude-(sonnet|opus|haiku)-([0-9]+)[.-]([0-9]{1,2})(?:\b|-)`)
22		claudeFamilyVersionPattern     = regexp.MustCompile(`\b(?:claude\s+)?(sonnet|opus|haiku)\s+([0-9]+(?:[.-][0-9]+){0,2})\b`)
23		claudeAliasPattern             = regexp.MustCompile(`(?m)(?:^|[\s'"])(sonnet|opus|haiku)(?:$|[\s'"])`)
24		claudeEffortPattern            = regexp.MustCompile(`--effort\s+<level>.*\(([^)]*)\)`)
25	)
26	
27	func ReadClaudeModelDiscoveryViaPTY(timeout time.Duration, opts ...QuotaPTYOption) (harnesses.ModelDiscoverySnapshot, error) {
28		cfg := quotaPTYOptions{binary: "claude"}
29		for _, opt := range opts {
30			if opt != nil {
31				opt(&cfg)
32			}
33		}
34		var snapshot harnesses.ModelDiscoverySnapshot
35		_, err := ptyquota.Run(context.Background(), ptyquota.Config{
36			HarnessName:  "claude",
37			Binary:       cfg.binary,
38			Args:         cfg.args,
39			Workdir:      cfg.workdir,
40			Env:          cfg.env,
41			Command:      "/model\r",
42			ReadyMarkers: []string{"❯", "> "},
43			DoneWhen:     claudeModelDiscoveryComplete,
44			Timeout:      timeout,
45			Size:         session.Size{Rows: 50, Cols: 220},
46			CassetteDir:  cfg.cassetteDir,
47			Discovery: func(text string) (cassette.DiscoveryRecord, error) {
48				snapshot = claudeDiscoveryFromText(text, "pty")
49				if len(snapshot.Models) == 0 {
50					return cassette.DiscoveryRecord{}, fmt.Errorf("no models found in claude /model output")
51				}
52				return discoveryRecord(snapshot), nil
53			},
54		})
55		if err != nil {
56			return harnesses.ModelDiscoverySnapshot{}, err
57		}
58		if len(snapshot.Models) == 0 {
59			return harnesses.ModelDiscoverySnapshot{}, fmt.Errorf("no models found in claude /model output")
60		}
61		return snapshot, nil
62	}
63	
64	func ReadClaudeModelDiscoveryFromCassette(dir string) (harnesses.ModelDiscoverySnapshot, error) {
65		reader, err := cassette.Open(dir)
66		if err != nil {
67			return harnesses.ModelDiscoverySnapshot{}, err
68		}
69		if rec := reader.Discovery(); rec != nil && len(rec.Models) > 0 {
70			return snapshotFromDiscoveryRecord(*rec), nil
71		}
72		text := reader.Final().FinalText
73		if text == "" {
74			frames := reader.Frames()
75			if len(frames) > 0 {
76				text = strings.Join(frames[len(frames)-1].Text, "\n")
77			}
78		}
79		snapshot := claudeDiscoveryFromText(text, "cassette")
80		if len(snapshot.Models) == 0 {
81			return harnesses.ModelDiscoverySnapshot{}, fmt.Errorf("no models found in claude model cassette")
82		}
83		return snapshot, nil
84	}
85	
86	func readClaudeReasoningFromHelp(ctx context.Context, binary string, args ...string) ([]string, error) {
87		if binary == "" {
88			binary = "claude"
89		}
90		if len(args) == 0 {
91			args = []string{"--help"}
92		}
93		cmd := exec.CommandContext(ctx, binary, args...)
94		out, err := cmd.CombinedOutput()
95		if err != nil {
96			return nil, fmt.Errorf("claude help: %w", err)
97		}
98		levels := parseClaudeReasoningLevels(string(out))
99		if len(levels) == 0 {
100			return nil, fmt.Errorf("claude help did not expose --effort levels")
101		}
102		return levels, nil
103	}
