105	// testClaudeModelDiscovery returns a minimal discovery snapshot for testing.
106	// It is not used in production code paths.
107	func testClaudeModelDiscovery() harnesses.ModelDiscoverySnapshot {
108		return harnesses.ModelDiscoverySnapshot{
109			CapturedAt:      time.Now().UTC(),
110			ReasoningLevels: []string{"low", "medium", "high", "xhigh", "max"},
111			FreshnessWindow: ClaudeModelDiscoveryFreshnessWindow.String(),
112		}
113	}
114	
115	func claudeModelDiscoveryComplete(text string) bool {
116		return len(parseClaudeModels(text)) > 0
117	}
118	
119	func claudeDiscoveryFromText(text, source string) harnesses.ModelDiscoverySnapshot {
120		snapshot := harnesses.ModelDiscoverySnapshot{
121			CapturedAt:      time.Now().UTC(),
122			FreshnessWindow: ClaudeModelDiscoveryFreshnessWindow.String(),
123		}
124		if source != "" {
125			snapshot.Source = source
126		}
127		if models := parseClaudeModels(text); len(models) > 0 {
128			snapshot.Models = models
129		}
130		if levels := parseClaudeReasoningLevels(text); len(levels) > 0 {
131			snapshot.ReasoningLevels = levels
132		}
133		return snapshot
134	}
135	
136	func parseClaudeModels(text string) []string {
137		text = stripANSI(strings.ReplaceAll(text, "\r\n", "\n"))
138		lower := strings.ToLower(text)
139		models := uniqueMatches(claudeFullModelPattern.FindAllString(lower, -1))
140		for _, match := range claudeFullFamilyVersionPattern.FindAllStringSubmatch(lower, -1) {
141			if len(match) > 3 {
142				models = appendUniqueString(models, match[1]+"-"+match[2]+"."+match[3])
143			}
144		}
145		for _, match := range claudeFamilyVersionPattern.FindAllStringSubmatch(lower, -1) {
146			if len(match) > 2 {
147				models = appendUniqueString(models, match[1]+"-"+strings.ReplaceAll(match[2], "-", "."))
148			}
149		}
150		for _, match := range claudeAliasPattern.FindAllStringSubmatch(lower, -1) {
151			if len(match) > 1 {
152				models = appendUniqueString(models, match[1])
153			}
154		}
155		return models
156	}
157	
158	func resolveClaudeFamilyAlias(model string, snapshot harnesses.ModelDiscoverySnapshot) string {
159		family := strings.ToLower(strings.TrimSpace(model))
160		if family != "sonnet" && family != "opus" && family != "haiku" {
161			return model
162		}
163		if resolved := latestClaudeFamilyVersion(family, snapshot.Models); resolved != "" {
164			return resolved
165		}
166		return model
167	}
168	
169	func latestClaudeFamilyVersion(family string, models []string) string {
170		prefix := family + "-"
171		best := ""
172		var bestParts []int
173		for _, model := range models {
174			model = strings.ToLower(strings.TrimSpace(model))
175			if !strings.HasPrefix(model, prefix) {
176				continue
177			}
178			parts, ok := parseClaudeVersionParts(strings.TrimPrefix(model, prefix))
179			if !ok {
180				continue
181			}
182			if best == "" || compareVersionParts(parts, bestParts) > 0 {
183				best = model
184				bestParts = parts
185			}
186		}
187		return best
188	}
189	
190	func parseClaudeVersionParts(version string) ([]int, bool) {
191		version = strings.ReplaceAll(version, "-", ".")
192		raw := strings.Split(version, ".")
193		if len(raw) == 0 {
194			return nil, false
195		}
196		parts := make([]int, 0, len(raw))
197		for _, part := range raw {
198			if part == "" {
199				return nil, false
200			}
201			n := 0
202			for _, r := range part {
203				if r < '0' || r > '9' {
204					return nil, false
205				}
206				n = n*10 + int(r-'0')
207			}
208			parts = append(parts, n)
209		}
210		return parts, true
211	}
212	
213	func compareVersionParts(a, b []int) int {
214		n := len(a)
215		if len(b) > n {
216			n = len(b)
217		}
218		for i := 0; i < n; i++ {
219			av, bv := 0, 0
220			if i < len(a) {
221				av = a[i]
222			}
223			if i < len(b) {
224				bv = b[i]
225			}
226			if av > bv {
227				return 1
228			}
229			if av < bv {
230				return -1
231			}
232		}
233		return 0
234	}
235	
236	func parseClaudeReasoningLevels(text string) []string {
237		text = stripANSI(strings.ReplaceAll(text, "\n", " "))
238		m := claudeEffortPattern.FindStringSubmatch(text)
239		if len(m) < 2 {
240			return nil
241		}
242		parts := strings.Split(m[1], ",")
243		out := make([]string, 0, len(parts))
244		for _, part := range parts {
245			out = appendUniqueString(out, strings.TrimSpace(part))
246		}
247		return out
248	}
249	
250	func discoveryRecord(snapshot harnesses.ModelDiscoverySnapshot) cassette.DiscoveryRecord {
251		return cassette.DiscoveryRecord{
252			Source:            snapshot.Source,
253			Status:            string(ptyquota.StatusOK),
254			Models:            append([]string(nil), snapshot.Models...),
