114	func resolveCodexModelAlias(model string, snapshot harnesses.ModelDiscoverySnapshot) string {
115		model = strings.ToLower(strings.TrimSpace(model))
116		if model == "" {
117			return model
118		}
119		switch {
120		case model == "gpt":
121			if resolved := latestCodexModel("", snapshot.Models); resolved != "" {
122				return resolved
123			}
124		case regexp.MustCompile(`^gpt-[0-9]+$`).MatchString(model):
125			if resolved := latestCodexModel(strings.TrimPrefix(model, "gpt-"), snapshot.Models); resolved != "" {
126				return resolved
127			}
128		}
129		return model
130	}
131	
132	func latestCodexModel(major string, models []string) string {
133		best := ""
134		var bestParts []int
135		bestHasSuffix := true
136		for _, model := range models {
137			candidate := strings.ToLower(strings.TrimSpace(model))
138			parts, hasSuffix, ok := parseCodexVersion(candidate)
139			if !ok {
140				continue
141			}
142			if major != "" && (len(parts) == 0 || fmt.Sprint(parts[0]) != major) {
143				continue
144			}
145			if best == "" || compareCodexVersion(parts, hasSuffix, bestParts, bestHasSuffix) > 0 {
146				best = candidate
147				bestParts = parts
148				bestHasSuffix = hasSuffix
149			}
150		}
151		return best
152	}
153	
154	func parseCodexVersion(model string) ([]int, bool, bool) {
155		if !strings.HasPrefix(model, "gpt-") {
156			return nil, false, false
157		}
158		rest := strings.TrimPrefix(model, "gpt-")
159		raw := strings.FieldsFunc(rest, func(r rune) bool { return r == '.' || r == '-' })
160		if len(raw) == 0 {
161			return nil, false, false
162		}
163		parts := make([]int, 0, len(raw))
164		hasSuffix := false
165		for _, part := range raw {
166			if part == "" {
167				return nil, false, false
168			}
169			n := 0
170			for _, r := range part {
171				if r < '0' || r > '9' {
172					hasSuffix = true
173					return parts, hasSuffix, len(parts) > 0
174				}
175				n = n*10 + int(r-'0')
176			}
177			parts = append(parts, n)
178		}
179		return parts, hasSuffix, true
180	}
181	
182	func compareCodexVersion(a []int, aHasSuffix bool, b []int, bHasSuffix bool) int {
183		n := len(a)
184		if len(b) > n {
185			n = len(b)
186		}
187		for i := 0; i < n; i++ {
188			av, bv := 0, 0
189			if i < len(a) {
190				av = a[i]
191			}
192			if i < len(b) {
193				bv = b[i]
194			}
195			if av > bv {
196				return 1
197			}
198			if av < bv {
199				return -1
200			}
201		}
202		if aHasSuffix == bHasSuffix {
203			return 0
204		}
205		if !aHasSuffix {
206			return 1
207		}
208		return -1
209	}
