215			Models:            append([]string(nil), snapshot.Models...),
216			ReasoningLevels:   append([]string(nil), snapshot.ReasoningLevels...),
217			CapturedAt:        snapshot.CapturedAt.UTC().Format(time.RFC3339),
218			FreshnessWindow:   snapshot.FreshnessWindow,
219			StalenessBehavior: "stale model discovery evidence requires authenticated PTY refresh before capability promotion",
220			Metadata:          map[string]any{"detail": snapshot.Detail},
221		}
222	}
