1	package codex
2	
3	import (
4		"context"
5		"fmt"
6		"os"
7		"strings"
8		"time"
9	
10		"golang.org/x/sync/singleflight"
11	
12		"github.com/easel/fizeau/internal/harnesses"
13	)
14	
15	// codexQuotaFreshness is the constant freshness window for codex quota
16	// evidence. Mirrors defaultCodexQuotaStaleAfter (kept as a separate name
17	// so the CONTRACT-004 method has a stable, contract-named constant).
18	const codexQuotaFreshness = defaultCodexQuotaStaleAfter
19	
20	// codexAccountFreshness is the constant freshness window for codex
21	// account evidence. Codex reads account metadata from auth.json which
22	// changes only on re-auth, so a long window is appropriate.
23	const codexAccountFreshness = 7 * 24 * time.Hour
24	
25	// supportedLimitIDs is the stable public set of Windows[].LimitID values
26	// codex's quota probes emit. Mirrored in doc.go for human readers.
27	var supportedLimitIDs = []string{
28		"codex",
29		"codex-weekly",
30	}
31	
32	// supportedAliases is the stable public set of family aliases
33	// ResolveModelAlias recognizes. Mirrored in doc.go for human readers.
34	var supportedAliases = []string{"gpt", "gpt-5"}
35	
36	// refreshGroup serializes concurrent RefreshQuota / RefreshAccount calls
37	// across all *Runner instances. Per CONTRACT-004 invariant #6 Runners are
38	// stateless wrappers — sharing the singleflight group at package scope
39	// keeps single-flight semantics correct when callers construct fresh
40	// runner instances per call (which the dispatcher does today).
41	var refreshGroup singleflight.Group
42	
43	// QuotaStatus implements harnesses.QuotaHarness. It reads the cached
44	// snapshot owned by this harness and projects it onto QuotaStatus. A
45	// missing or undecodable cache is reported as State=QuotaUnavailable on
46	// a valid QuotaStatus value (no error) per CONTRACT-004 §"Errors are
47	// reserved for call failure."
48	func (r *Runner) QuotaStatus(ctx context.Context, now time.Time) (harnesses.QuotaStatus, error) {
49		if err := ctx.Err(); err != nil {
50			return harnesses.QuotaStatus{}, err
51		}
52		snap, ok := readCodexQuota()
53		if !ok || snap == nil {
54			return harnesses.QuotaStatus{
55				Source:            "cache",
56				State:             harnesses.QuotaUnavailable,
57				RoutingPreference: harnesses.RoutingPreferenceUnknown,
58				Reason:            "no cached snapshot",
59			}, nil
60		}
61		return codexQuotaStatusFromSnapshot(snap, now), nil
62	}
63	
64	// RefreshQuota implements harnesses.QuotaHarness. It probes the codex
65	// CLI via PTY first and folds the session-token-count source in as an
66	// internal fallback when the PTY probe yields no evidence. The result
67	// is persisted through the harness's owned cache. Single-flight per
68	// harness: concurrent callers share one cohort and observe the
69	// just-written cached state. Probe failure is reported as
70	// State=QuotaUnavailable on a valid QuotaStatus value, not as an error.
71	func (r *Runner) RefreshQuota(ctx context.Context) (harnesses.QuotaStatus, error) {
72		if err := ctx.Err(); err != nil {
73			return harnesses.QuotaStatus{}, err
74		}
75		v, err, _ := refreshGroup.Do("refresh-quota", func() (any, error) {
76			return r.refreshQuotaLocked(ctx), nil
77		})
78		if err != nil {
79			return harnesses.QuotaStatus{}, err
80		}
81		return v.(harnesses.QuotaStatus), nil
82	}
83	
84	// refreshQuotaLocked is the single-flight critical section. It runs the
85	// PTY probe, falls back to the session-token-count source when PTY
86	// yields no evidence, writes the cache on success, and returns the
87	// projected status. Total probe failure is folded into
88	// State=QuotaUnavailable.
89	func (r *Runner) refreshQuotaLocked(ctx context.Context) harnesses.QuotaStatus {
90		now := time.Now()
91		timeout := codexQuotaFreshness
92		if deadline, ok := ctx.Deadline(); ok {
93			remaining := time.Until(deadline)
94			if remaining > 0 && remaining < timeout {
95				timeout = remaining
96			}
97		}
98		var opts []QuotaPTYOption
99		if r.Binary != "" {
100			opts = append(opts, WithQuotaPTYCommand(r.Binary))
101		}
102		windows, _, ptyErr := captureCodexQuotaViaPTY(ctx, timeout, opts...)
103		if ptyErr == nil && len(windows) > 0 {
104			snap := codexQuotaSnapshot{
105				CapturedAt: now.UTC(),
106				Windows:    windows,
107				Source:     "pty",
108				Account:    readCodexAccountOrNil(),
109			}
110			if path, pathErr := codexQuotaCachePath(); pathErr == nil {
111				_ = writeCodexQuota(path, snap)
112			}
113			return codexQuotaStatusFromSnapshot(&snap, now)
114		}
115		if snap, ok := readCodexQuotaFromSessionTokenCounts(WithCodexSessionTokenCountNow(now)); ok && snap != nil {
116			if snap.Account == nil {
117				snap.Account = readCodexAccountOrNil()
118			}
119			if path, pathErr := codexQuotaCachePath(); pathErr == nil {
120				_ = writeCodexQuota(path, *snap)
121			}
122			return codexQuotaStatusFromSnapshot(snap, now)
123		}
124		state := harnesses.QuotaUnavailable
125		reason := "no quota evidence from PTY probe or session token-count fallback"
126		if ptyErr != nil {
127			reason = ptyErr.Error()
128			lower := strings.ToLower(reason)
129			if strings.Contains(lower, "not found in path") || strings.Contains(lower, "executable file not found") {
130				state = harnesses.QuotaUnauthenticated
131			}
132		}
133		return harnesses.QuotaStatus{
134			Source:            "pty",
135			CapturedAt:        now.UTC(),
136			State:             state,
137			RoutingPreference: harnesses.RoutingPreferenceUnknown,
138			Reason:            reason,
139		}
140	}
