152	// AccountStatus implements harnesses.AccountHarness. Codex reads
153	// non-secret account metadata from auth.json via codexAuthPath /
154	// readCodexAccount; this method projects that onto AccountSnapshot.
155	func (r *Runner) AccountStatus(ctx context.Context, now time.Time) (harnesses.AccountSnapshot, error) {
156		if err := ctx.Err(); err != nil {
157			return harnesses.AccountSnapshot{}, err
