162	// RefreshAccount implements harnesses.AccountHarness by re-reading the
163	// codex auth file (the source of account evidence) and projecting onto
164	// AccountSnapshot. Single-flight per harness via the package-scoped
165	// singleflight group.
166	func (r *Runner) RefreshAccount(ctx context.Context) (harnesses.AccountSnapshot, error) {
167		if err := ctx.Err(); err != nil {
168			return harnesses.AccountSnapshot{}, err
169		}
170		v, err, _ := refreshGroup.Do("refresh-account", func() (any, error) {
171			return readCodexAccountSnapshot(time.Now()), nil
172		})
173		if err != nil {
174			return harnesses.AccountSnapshot{}, err
175		}
176		return v.(harnesses.AccountSnapshot), nil
