184	// readCodexAccountSnapshot reads codex auth state and projects it onto
185	// AccountSnapshot. A missing or unreadable auth file is reported as
186	// Unauthenticated on a valid snapshot value, not as an error.
187	func readCodexAccountSnapshot(now time.Time) harnesses.AccountSnapshot {
188		snap := harnesses.AccountSnapshot{Source: "cache"}
189		if path, err := codexAuthPath(); err == nil && path != "" {
190			snap.Source = path
191			if st, statErr := os.Stat(path); statErr == nil {
192				snap.CapturedAt = st.ModTime().UTC()
193				snap.Fresh = now.UTC().Sub(snap.CapturedAt) <= codexAccountFreshness
194			}
195		}
196		account, ok := readCodexAccount()
197		if !ok || account == nil {
198			snap.Unauthenticated = true
199			return snap
200		}
201		snap.Email = account.Email
202		snap.PlanType = account.PlanType
203		snap.OrgName = account.OrgName
204		if strings.TrimSpace(account.PlanType) == "" {
205			snap.Unauthenticated = true
206		} else {
207			snap.Authenticated = true
208		}
209		return snap
210	}
