212	// DefaultModelSnapshot implements harnesses.ModelDiscoveryHarness. It calls
213	// the live PTY discovery helper with a sensible timeout; on failure,
214	// returns a snapshot with empty Models and error detail.
215	func (r *Runner) DefaultModelSnapshot() (harnesses.ModelDiscoverySnapshot, error) {
216		timeout := 10 * time.Second
217		var opts []QuotaPTYOption
218		if r.Binary != "" {
219			opts = append(opts, WithQuotaPTYCommand(r.Binary))
220		}
221		snapshot, err := ReadCodexModelDiscoveryViaPTY(timeout, opts...)
222		if err != nil {
223			return harnesses.ModelDiscoverySnapshot{}, fmt.Errorf("model discovery PTY: %w", err)
224		}
225		if len(snapshot.Models) == 0 {
226			return harnesses.ModelDiscoverySnapshot{}, harnesses.ErrModelDiscoveryEvidenceMissing
227		}
228		return snapshot, nil
229	}
