231	// ResolveModelAlias implements harnesses.ModelDiscoveryHarness. Returns
232	// harnesses.ErrAliasNotResolvable when the supplied family is not a
233	// recognized codex alias or when the supplied discovery snapshot has
234	// no concrete model matching the family.
235	func (r *Runner) ResolveModelAlias(family string, snapshot harnesses.ModelDiscoverySnapshot) (string, error) {
236		normalized := strings.ToLower(strings.TrimSpace(family))
237		if !isSupportedCodexAlias(normalized) {
238			return "", harnesses.ErrAliasNotResolvable
239		}
240		resolved := resolveCodexModelAlias(normalized, snapshot)
241		if resolved == "" || resolved == normalized {
242			// existing helper returns the input string when no concrete
243			// model matches; treat that as unresolvable per CONTRACT-004.
244			return "", harnesses.ErrAliasNotResolvable
245		}
246		return resolved, nil
247	}
