263	// codexQuotaStatusFromSnapshot projects the per-harness snapshot onto
264	// harnesses.QuotaStatus, deriving State and RoutingPreference via the
265	// existing decideCodexQuotaRouting helper so today's "PreferCodex +
266	// freshness" semantics map cleanly onto CONTRACT-004's RoutingPreference
267	// enum.
268	func codexQuotaStatusFromSnapshot(snap *codexQuotaSnapshot, now time.Time) harnesses.QuotaStatus {
269		decision := decideCodexQuotaRouting(snap, now, codexQuotaFreshness)
270		pref, state := mapCodexRoutingPreference(decision)
271		status := harnesses.QuotaStatus{
272			Source:            snap.Source,
273			CapturedAt:        snap.CapturedAt,
274			Fresh:             decision.Fresh,
275			Age:               decision.Age,
276			State:             state,
277			Windows:           append([]harnesses.QuotaWindow(nil), snap.Windows...),
278			RoutingPreference: pref,
279			Reason:            decision.Reason,
280		}
281		if snap.Account != nil {
282			acct := codexAccountSnapshotFromQuotaSnapshot(snap, now)
283			status.Account = &acct
284		}
285		return status
286	}
287	
288	// mapCodexRoutingPreference translates today's PreferCodex+freshness
289	// decision into the CONTRACT-004 (RoutingPreference, QuotaStateValue)
290	// pair. Legacy semantics: missing snapshot ⇒ Unavailable/Unknown;
291	// stale ⇒ Stale/Blocked ("assume limited"); fresh+PreferCodex ⇒
292	// OK/Available; fresh+!PreferCodex ⇒ Blocked/Blocked.
293	func mapCodexRoutingPreference(d codexQuotaRoutingDecision) (harnesses.RoutingPreference, harnesses.QuotaStateValue) {
294		if !d.SnapshotPresent {
295			return harnesses.RoutingPreferenceUnknown, harnesses.QuotaUnavailable
296		}
297		if !d.Fresh {
298			return harnesses.RoutingPreferenceBlocked, harnesses.QuotaStale
299		}
300		if d.PreferCodex {
301			return harnesses.RoutingPreferenceAvailable, harnesses.QuotaOK
302		}
303		return harnesses.RoutingPreferenceBlocked, harnesses.QuotaBlocked
304	}
305	
306	// codexAccountSnapshotFromQuotaSnapshot derives an AccountSnapshot from
307	// the quota cache's embedded Account field. An empty plan-type is
308	// reported as unauthenticated evidence rather than positive
309	// authentication.
310	func codexAccountSnapshotFromQuotaSnapshot(snap *codexQuotaSnapshot, now time.Time) harnesses.AccountSnapshot {
311		out := harnesses.AccountSnapshot{
312			Source:     "cache",
313			CapturedAt: snap.CapturedAt,
314			Fresh:      isCodexQuotaFresh(snap, now, codexAccountFreshness),
315		}
316		if snap.Account == nil {
317			return out
318		}
319		plan := strings.TrimSpace(snap.Account.PlanType)
320		out.PlanType = plan
321		out.Email = snap.Account.Email
322		out.OrgName = snap.Account.OrgName
323		if plan == "" {
324			out.Unauthenticated = true
325		} else {
326			out.Authenticated = true
327		}
328		return out
329	}
