194	func (r *Runner) ResolveModelAlias(family string, snapshot harnesses.ModelDiscoverySnapshot) (string, error) {
195		normalized := strings.ToLower(strings.TrimSpace(family))
196		if !isSupportedGeminiAlias(normalized) {
197			return "", harnesses.ErrAliasNotResolvable
198		}
199		resolved := resolveGeminiModelAlias(normalized, snapshot)
200		if resolved == "" || resolved == normalized {
201			// resolveGeminiModelAlias returns the input unchanged when no
202			// concrete model matches. Treat that as not-resolvable so the
203			// CONTRACT-004 negative-path semantics are preserved.
204			return "", harnesses.ErrAliasNotResolvable
205		}
206		return resolved, nil
207	}
