223	// geminiQuotaStatusFromSnapshot projects the per-harness snapshot onto
224	// harnesses.QuotaStatus, deriving State and RoutingPreference via the
225	// existing decideGeminiQuotaRouting helper. Tier facts (Flash / Flash
226	// Lite / Pro) live in Windows with their distinguishing LimitID; no tier
227	// names appear in Detail.
228	func geminiQuotaStatusFromSnapshot(snap *geminiQuotaSnapshot, now time.Time) harnesses.QuotaStatus {
229		decision := decideGeminiQuotaRouting(snap, now, geminiQuotaFreshness)
230		pref, state := mapGeminiRoutingPreference(decision)
231		status := harnesses.QuotaStatus{
232			Source:            snap.Source,
233			CapturedAt:        snap.CapturedAt,
234			Fresh:             decision.fresh,
235			Age:               decision.age,
236			State:             state,
237			Windows:           append([]harnesses.QuotaWindow(nil), snap.Windows...),
238			RoutingPreference: pref,
239			Reason:            decision.reason,
240		}
241		if snap.Account != nil {
242			acct := harnesses.AccountSnapshot{
243				Source:     "cache",
244				CapturedAt: snap.CapturedAt,
245				Fresh:      isGeminiQuotaFresh(snap, now, geminiAccountFreshness),
246				PlanType:   snap.Account.PlanType,
247				Email:      snap.Account.Email,
248				OrgName:    snap.Account.OrgName,
249			}
250			if snap.Account.PlanType != "" || snap.Account.Email != "" {
251				acct.Authenticated = true
252			}
253			status.Account = &acct
254		}
255		return status
256	}
257	
258	// mapGeminiRoutingPreference translates today's preferGemini+freshness
259	// decision into the CONTRACT-004 (RoutingPreference, QuotaStateValue)
260	// pair. Legacy semantics: missing snapshot ⇒ Unavailable/Unknown;
261	// stale ⇒ Stale/Blocked ("assume limited"); fresh+preferGemini ⇒
262	// OK/Available; fresh+!preferGemini ⇒ Blocked/Blocked.
263	func mapGeminiRoutingPreference(d geminiQuotaRoutingDecision) (harnesses.RoutingPreference, harnesses.QuotaStateValue) {
264		if !d.snapshotPresent {
265			return harnesses.RoutingPreferenceUnknown, harnesses.QuotaUnavailable
266		}
267		if !d.fresh {
268			return harnesses.RoutingPreferenceBlocked, harnesses.QuotaStale
269		}
270		if d.preferGemini {
271			return harnesses.RoutingPreferenceAvailable, harnesses.QuotaOK
272		}
273		return harnesses.RoutingPreferenceBlocked, harnesses.QuotaBlocked
274	}
