276	// geminiAccountSnapshotFromAuth projects an authSnapshot onto the
277	// universal AccountSnapshot type. Authenticated is true iff the
278	// underlying auth evidence reports an authenticated session;
279	// Unauthenticated is the explicit negative signal so the projection
280	// distinguishes "no evidence" from "evidence says signed out".
281	func geminiAccountSnapshotFromAuth(auth authSnapshot) harnesses.AccountSnapshot {
282		out := harnesses.AccountSnapshot{
283			Source:     auth.Source,
284			CapturedAt: auth.CapturedAt,
285			Fresh:      auth.Fresh,
286			Detail:     auth.Detail,
287		}
288		if auth.Account != nil {
289			out.PlanType = auth.Account.PlanType
290			out.Email = auth.Account.Email
291			out.OrgName = auth.Account.OrgName
292		}
293		if auth.Authenticated {
294			out.Authenticated = true
295		} else {
296			out.Unauthenticated = true
297		}
298		return out
299	}
