1	package gemini
2	
3	import (
4		"fmt"
5		"regexp"
6		"strings"
7		"time"
8	
9		"github.com/easel/fizeau/internal/harnesses"
10	)
11	
12	const GeminiModelDiscoveryFreshnessWindow = 24 * time.Hour
13	
14	var (
15		geminiANSISequencePattern = regexp.MustCompile(`\x1b\[[0-9;?]*[ -/]*[@-~]`)
16		geminiModelPattern        = regexp.MustCompile(`\bgemini-[A-Za-z0-9][A-Za-z0-9._-]*\b`)
17		geminiMajorPattern        = regexp.MustCompile(`^gemini-[0-9]+(?:[.-][0-9]+)?$`)
18	)
19	
20	// testGeminiModelDiscovery returns a minimal discovery snapshot for testing.
21	// It is not used in production code paths.
22	func testGeminiModelDiscovery() harnesses.ModelDiscoverySnapshot {
23		return harnesses.ModelDiscoverySnapshot{
24			CapturedAt:      time.Now().UTC(),
25			FreshnessWindow: GeminiModelDiscoveryFreshnessWindow.String(),
26		}
27	}
28	
29	// ModelDiscoveryFromText extracts Gemini model IDs from caller-provided CLI
30	// output without assuming a current default model list.
31	func ModelDiscoveryFromText(text, source string) harnesses.ModelDiscoverySnapshot {
32		snapshot := harnesses.ModelDiscoverySnapshot{
33			CapturedAt:      time.Now().UTC(),
34			FreshnessWindow: GeminiModelDiscoveryFreshnessWindow.String(),
35		}
36		if source == "" {
37			source = "cli-output:gemini"
38		}
39		snapshot.Source = source
40		if models := parseGeminiModels(text); len(models) > 0 {
41			snapshot.Models = models
42		}
43		return snapshot
44	}
45	
46	func parseGeminiModels(text string) []string {
47		text = geminiANSISequencePattern.ReplaceAllString(strings.ReplaceAll(text, "\r\n", "\n"), "")
48		return uniqueGeminiStrings(geminiModelPattern.FindAllString(text, -1))
49	}
50	
51	func uniqueGeminiStrings(values []string) []string {
52		seen := map[string]bool{}
53		out := make([]string, 0, len(values))
54		for _, value := range values {
55			value = strings.TrimSpace(value)
56			if value == "" || value == "gemini-cli" || seen[value] {
57				continue
58			}
59			seen[value] = true
60			out = append(out, value)
61		}
62		return out
63	}
64	
65	func resolveGeminiModelAlias(model string, snapshot harnesses.ModelDiscoverySnapshot) string {
66		model = strings.ToLower(strings.TrimSpace(model))
67		if model == "" {
68			return model
69		}
70		if model == "gemini" {
71			if resolved := latestGeminiModel("", snapshot.Models); resolved != "" {
72				return resolved
73			}
74			return model
75		}
76		if geminiMajorPattern.MatchString(model) {
77			prefix := strings.TrimPrefix(model, "gemini-")
78			if resolved := latestGeminiModel(prefix, snapshot.Models); resolved != "" {
79				return resolved
80			}
81		}
82		return model
83	}
84	
85	func latestGeminiModel(prefix string, models []string) string {
86		best := ""
87		var bestParts []int
88		bestRank := -1
89		for _, model := range models {
90			candidate := strings.ToLower(strings.TrimSpace(model))
91			parts, variant, ok := parseGeminiVersion(candidate)
92			if !ok {
93				continue
94			}
95			if prefix != "" && !strings.HasPrefix(versionKey(parts), strings.ReplaceAll(prefix, "-", ".")) {
96				continue
97			}
98			rank := geminiVariantRank(variant)
99			if best == "" || compareGeminiVersion(parts, rank, bestParts, bestRank) > 0 {
100				best = candidate
101				bestParts = parts
102				bestRank = rank
103			}
104		}
105		return best
106	}
107	
108	func parseGeminiVersion(model string) ([]int, string, bool) {
109		if !strings.HasPrefix(model, "gemini-") {
110			return nil, "", false
111		}
112		rest := strings.TrimPrefix(model, "gemini-")
113		raw := strings.FieldsFunc(rest, func(r rune) bool { return r == '.' || r == '-' })
114		if len(raw) == 0 {
115			return nil, "", false
116		}
117		parts := make([]int, 0, len(raw))
118		var variant []string
119		for _, part := range raw {
120			if part == "" {
121				return nil, "", false
122			}
123			n := 0
124			numeric := true
125			for _, r := range part {
126				if r < '0' || r > '9' {
127					numeric = false
128					break
129				}
130				n = n*10 + int(r-'0')
131			}
132			if numeric && len(variant) == 0 {
133				parts = append(parts, n)
134				continue
135			}
136			variant = append(variant, part)
137		}
138		if len(parts) == 0 {
139			return nil, "", false
140		}
141		return parts, strings.Join(variant, "-"), true
142	}
143	
144	func versionKey(parts []int) string {
145		out := make([]string, len(parts))
146		for i, part := range parts {
147			out[i] = fmt.Sprint(part)
148		}
149		return strings.Join(out, ".")
150	}
151	
152	func geminiVariantRank(variant string) int {
153		switch {
154		case strings.Contains(variant, "pro"):
155			return 30
156		case strings.Contains(variant, "flash") && !strings.Contains(variant, "lite"):
157			return 20
158		case strings.Contains(variant, "flash-lite"), strings.Contains(variant, "lite"):
159			return 10
160		case variant == "":
161			return 0
162		default:
163			return 5
164		}
165	}
166	
167	func compareGeminiVersion(a []int, aRank int, b []int, bRank int) int {
168		n := len(a)
169		if len(b) > n {
170			n = len(b)
171		}
172		for i := 0; i < n; i++ {
173			av, bv := 0, 0
174			if i < len(a) {
175				av = a[i]
176			}
177			if i < len(b) {
178				bv = b[i]
179			}
180			if av > bv {
181				return 1
182			}
183			if av < bv {
184				return -1
185			}
186		}
187		switch {
188		case aRank > bRank:
189			return 1
190		case aRank < bRank:
191			return -1
192		default:
193			return 0
194		}
195	}
