169	func (r *Runner) runStreaming(ctx context.Context, binary string, req harnesses.ExecuteRequest, out chan<- harnesses.Event, seq *int64) (agg *streamAggregate, exitCode int, stderr string, runErr error, status string) {
170		base := r.BaseArgs
171		if base == nil {
172			base = []string{"run", "--format", "json"}
173		}
174		args := append([]string{}, base...)
175	
176		// opencode run auto-approves all tool permissions; no extra flags per level.
177	
178		// WorkDir flag: --dir <dir>
179		if req.WorkDir != "" {
180			args = append(args, "--dir", req.WorkDir)
181		}
182	
183		// Model flag: -m <model>
184		if req.Model != "" {
185			args = append(args, "-m", opencodeModelArg(req.Provider, req.Model))
186		}
187	
188		// Reasoning flag: --variant <reasoning>
189		if value := harnesses.AdapterReasoningValue(req); value != "" {
190			args = append(args, "--variant", value)
191		}
192	
193		promptMode := r.PromptMode
194		if promptMode == "" {
195			promptMode = "arg"
196		}
197		if promptMode == "arg" && req.Prompt != "" {
198			args = append(args, req.Prompt)
199		}
200	
201		runCtx, cancel := context.WithCancel(ctx)
202		defer cancel()
203	
204		cmd := harnesses.HarnessCommand(runCtx, binary, args...)
205		if req.WorkDir != "" {
206			cmd.Dir = req.WorkDir
207		}
208		if promptMode != "arg" {
209			cmd.Stdin = strings.NewReader(req.Prompt)
210		}
211		setProcessGroup(cmd)
212	
213		stdoutPipe, err := cmd.StdoutPipe()
214		if err != nil {
215			return nil, -1, "", err, "failed"
216		}
217		stderrPipe, err := cmd.StderrPipe()
218		if err != nil {
219			return nil, -1, "", err, "failed"
220		}
221	
222		if err := cmd.Start(); err != nil {
223			return nil, -1, "", err, "failed"
224		}
225		defer killProcessGroup(cmd)
226		_ = harnesses.RegisterHarnessSession(req.SessionLogDir, req.SessionID, "opencode", cmd)
227	
228		progressLog, _ := harnesses.OpenProgressLog(req.SessionLogDir, req.SessionID, "opencode")
229		if progressLog != nil {
230			defer progressLog.Close()
231		}
232	
233		parserReader, parserWriter := io.Pipe()
234		parseDone := make(chan struct{})
235		var parseAgg *streamAggregate
236		var parseErr error
237		go func() {
238			defer close(parseDone)
239			mirrored, mirrorDone := harnesses.MirrorEvents(out, progressLog, ctx)
240			parseAgg, parseErr = parseOpencodeStream(runCtx, parserReader, mirrored, req.Metadata, seq)
241			close(mirrored)
242			<-mirrorDone
243		}()
244	
245		stdoutDone := make(chan struct{})
246		go func() {
247			defer close(stdoutDone)
248			_, _ = io.Copy(parserWriter, stdoutPipe)
249			_ = parserWriter.Close()
250		}()
251	
252		var stderrBuf strings.Builder
253		stderrDone := make(chan struct{})
254		go func() {
255			defer close(stderrDone)
256			_, _ = io.Copy(&stringBuilderWriter{&stderrBuf}, stderrPipe)
257		}()
258	
259		var timedOut atomic.Bool
260		if req.Timeout > 0 {
261			stop := make(chan struct{})
262			go func() {
263				select {
264				case <-stop:
265				case <-time.After(req.Timeout):
266					timedOut.Store(true)
267					cancel()
268					killProcessGroup(cmd)
269				}
270			}()
271			defer close(stop)
272		}
273	
274		// Wait for stdout to be fully read; context cancellation also wakes us up.
275		// Either way, the defer ensures process group is killed on function exit.
276		select {
277		case <-runCtx.Done():
278		case <-stdoutDone:
279		}
280	
281		<-stderrDone
282		<-parseDone
283		runErr = cmd.Wait()
284		stderr = stderrBuf.String()
285	
286		switch {
287		case timedOut.Load():
288			return parseAgg, -1, stderr, context.DeadlineExceeded, "timed_out"
289		case ctx.Err() != nil && errors.Is(ctx.Err(), context.Canceled):
290			return parseAgg, -1, stderr, ctx.Err(), "cancelled"
291		case ctx.Err() != nil && errors.Is(ctx.Err(), context.DeadlineExceeded):
292			return parseAgg, -1, stderr, ctx.Err(), "timed_out"
293		case runErr != nil:
294			ec := -1
295			var exitErr *osexec.ExitError
296			if errors.As(runErr, &exitErr) {
297				ec = exitErr.ExitCode()
298			}
299			return parseAgg, ec, stderr, runErr, "failed"
300		}
301		if parseErr != nil && !errors.Is(parseErr, context.Canceled) {
302			return parseAgg, 0, stderr, parseErr, "failed"
303		}
304		return parseAgg, 0, stderr, nil, "success"
305	}
