21	// Runner is the subprocess-backed pi harness. It launches pi in
22	// JSON print mode, parses each JSONL line into harness Events, and emits a
23	// final Event when the subprocess exits.
24	//
25	// Pi emits JSONL where each line is a JSON object. The relevant event types:
26	//   - type=text_end or type=text_delta carries message.usage or partial.usage
27	//   - Final output text is in the last line's response field
28	type Runner struct {
29		// Binary is the absolute path to the pi executable. When empty the
30		// runner resolves "pi" via PATH at Execute time.
31		Binary string
32	
33		// BaseArgs is prepended to the per-request argument list.
34		// Pi default: defaultBaseArgs.
35		BaseArgs []string
36	
37		// PromptMode controls how the prompt is delivered:
38		//   "arg" (default) — prompt is appended as the final positional argument
39		//   "stdin"         — prompt is piped on stdin
40		PromptMode string
41	
42		// EventBuffer overrides the per-Execute channel buffer size.
43		EventBuffer int
44	}
