269	func decodeOpenCodeModelEvidence(model, raw string) (openCodeModelEvidence, error) {
270		var env struct {
271			ID         string          `json:"id"`
272			ProviderID string          `json:"providerID"`
273			Status     string          `json:"status"`
274			Cost       json.RawMessage `json:"cost"`
275			Limit      struct {
276				Context int `json:"context"`
277				Output  int `json:"output"`
278			} `json:"limit"`
279			Capabilities struct {
280				Reasoning  bool `json:"reasoning"`
281				ToolCall   bool `json:"toolcall"`
282				Attachment bool `json:"attachment"`
283			} `json:"capabilities"`
284			Variants map[string]json.RawMessage `json:"variants"`
285		}
286		if err := json.Unmarshal([]byte(raw), &env); err != nil {
287			return openCodeModelEvidence{}, err
288		}
289		evidence := openCodeModelEvidence{
290			Model:        model,
291			ProviderID:   env.ProviderID,
292			ModelID:      env.ID,
293			Status:       env.Status,
294			ContextLimit: env.Limit.Context,
295			OutputLimit:  env.Limit.Output,
296			Reasoning:    env.Capabilities.Reasoning,
297			ToolCall:     env.Capabilities.ToolCall,
298			Attachment:   env.Capabilities.Attachment,
299			Variants:     sortedOpenCodeVariantNames(env.Variants),
300		}
301		if len(env.Cost) > 0 && string(env.Cost) != "null" {
302			var cost struct {
303				Input  float64 `json:"input"`
304				Output float64 `json:"output"`
305				Cache  struct {
306					Read  float64 `json:"read"`
307					Write float64 `json:"write"`
308				} `json:"cache"`
309			}
310			if err := json.Unmarshal(env.Cost, &cost); err != nil {
311				return openCodeModelEvidence{}, err
312			}
313			evidence.Cost = &openCodeModelCost{
314				InputUSDPerMTok:      cost.Input,
315				OutputUSDPerMTok:     cost.Output,
316				CacheReadUSDPerMTok:  cost.Cache.Read,
317				CacheWriteUSDPerMTok: cost.Cache.Write,
318			}
319		}
320		return evidence, nil
321	}
