418	// snapshotFromDiscoveryRecord converts a cassette DiscoveryRecord to a ModelDiscoverySnapshot.
419	func snapshotFromDiscoveryRecord(rec cassette.DiscoveryRecord) harnesses.ModelDiscoverySnapshot {
420		capturedAt, _ := time.Parse(time.RFC3339, rec.CapturedAt)
421		detail, _ := rec.Metadata["detail"].(string)
422		return harnesses.ModelDiscoverySnapshot{
423			CapturedAt:      capturedAt,
424			Models:          append([]string(nil), rec.Models...),
425			ReasoningLevels: append([]string(nil), rec.ReasoningLevels...),
426			Source:          rec.Source,
427			FreshnessWindow: rec.FreshnessWindow,
428			Detail:          detail,
429		}
430	}
